import CompareIcon from '@jetbrains/icons/compare.svg'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import * as React from 'react'
import {useNavigate} from 'react-router'

import useStorageSyncValue, {SyncStorageKey} from '../../../../hooks/useStorageSyncValue'
import type {State} from '../../../../reducers/types'
import {getCompareBuildHref} from '../../../../routes'
import {getExtensionEndpoint, getIsSakuraUI} from '../../../../selectors'
import {stringifyId, toBuildId} from '../../../../types'
import type {BuildId} from '../../../../types'

import {useAppSelector} from 'src/hooks/react-redux'

export function useIsComparable(): boolean {
  return useAppSelector((state: State) => Boolean(getExtensionEndpoint(state, 'builds-diff')))
}

export function useCompareDropdownActionItem(
  buildId: BuildId | null | undefined,
): ListDataItem | null | undefined {
  const isComparable = useIsComparable()
  const navigate = useNavigate()
  const [sourceId, setSourceId] = useStorageSyncValue(SyncStorageKey.COMPARE_BUILD_SOURCE)
  const sourceBuildId = sourceId != null ? toBuildId(sourceId) : null
  const addSourceId = React.useCallback(() => {
    setSourceId(stringifyId(buildId))
  }, [buildId, setSourceId])
  const isSakuraUI = useAppSelector(getIsSakuraUI)
  const compareWithSelected = React.useCallback(
    (_: unknown, event: Event | React.MouseEvent | React.SyntheticEvent) => {
      if (sourceBuildId != null) {
        const href = `${getCompareBuildHref(sourceBuildId)}?withBuildId=${stringifyId(buildId)}`

        if (
          event != null &&
          (navigator.platform === 'MacIntel'
            ? 'metaKey' in event && event.metaKey
            : 'ctrlKey' in event && event.ctrlKey)
        ) {
          window.open(href, '_blank')
        } else {
          navigate(href)
          window.scrollTo(0, 0)
        }

        setSourceId(null)
      }
    },
    [buildId, setSourceId, sourceBuildId, navigate],
  )
  return React.useMemo(() => {
    if (!isComparable || !isSakuraUI) {
      return null
    }

    if (sourceId == null) {
      return {
        label: 'Select for comparison...',
        glyph: CompareIcon,
        onClick: addSourceId,
      }
    }

    if (buildId === sourceBuildId) {
      return null
    }

    return {
      label: 'Add to comparison',
      glyph: CompareIcon,
      onClick: compareWithSelected,
    }
  }, [isComparable, isSakuraUI, sourceId, buildId, sourceBuildId, compareWithSelected, addSourceId])
}
