import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'
import type {HTMLAttributes} from 'react'
import {Suspense, useEffect, useRef} from 'react'
import {ErrorBoundary, useErrorBoundary} from 'react-error-boundary'
import {useLocation} from 'react-router'

import Plugin from '../../common/Plugin/Plugin'

import styles from './BreadcrumbsPanel.module.css'

function Fallback() {
  const {resetBoundary} = useErrorBoundary()
  const location = useLocation()
  const initialLocation = useRef(location)
  useEffect(() => {
    if (location !== initialLocation.current) {
      resetBoundary()
    }
  }, [location, resetBoundary])
  return null
}

type Props = HTMLAttributes<HTMLDivElement>
export default function BreadcrumbsPanel({className, children, ...restProps}: Props) {
  return (
    <div className={classNames(styles.panel, className)} {...restProps}>
      <div className={styles.breadcrumbs}>
        <ErrorBoundary fallback={<Fallback />}>
          <Suspense>{children}</Suspense>
        </ErrorBoundary>
      </div>
      <Plugin placeId={PlaceId.HEADER_RIGHT} />
    </div>
  )
}
