import {FullLogTarget} from '../BuildLog.types'
import {parseShowLogParam} from '../BuildLog.utils'
import {updateFullLogState} from '../FullBuildLog/FullBuildLog.actions'

export const setShowLog = (showLog: string | null | undefined) => {
  const param = parseShowLogParam(showLog)
  return updateFullLogState({
    target: FullLogTarget.POPUP,
    ...param,
  })
}
