import classNames from 'classnames'
import {Resizable} from 're-resizable'
import type {ReactNode} from 'react'

import {RESIZABLE_ENABLE_CONFIG, RESIZABLE_HANDLE_CLASSES} from '../ToolPanelFooter.consts'
import styles from '../ToolPanelFooter.module.css'
import {getPanelSize} from '../ToolPanelFooter.utils'

type Props = {
  minPanelHeight: number
  maxPanelHeight: number
  calculatedPanelHeight: number
  onResize: (
    event: unknown,
    direction: unknown,
    refToElement: unknown,
    delta: {height: number; width: number},
  ) => void
  onResizeStop: (
    event: unknown,
    direction: unknown,
    refToElement: unknown,
    delta: {height: number; width: number},
  ) => void
  children: ReactNode
}
function ToolPanelFooterContent({
  children,
  minPanelHeight,
  maxPanelHeight,
  calculatedPanelHeight,
  onResize,
  onResizeStop,
}: Props) {
  return (
    <aside className={classNames(styles.footerPanel)}>
      <Resizable
        className={styles.resizable}
        handleClasses={RESIZABLE_HANDLE_CLASSES}
        enable={RESIZABLE_ENABLE_CONFIG}
        size={getPanelSize(calculatedPanelHeight)}
        minHeight={minPanelHeight}
        maxHeight={Math.round(maxPanelHeight)}
        onResize={onResize}
        onResizeStop={onResizeStop}
      >
        {children}
      </Resizable>
    </aside>
  )
}
export default ToolPanelFooterContent
