import type {AppThunk} from '../../../actions/types'
import {getDefaultProjectTab, tabExists} from '../../../selectors'
import type {TabId, ProjectId} from '../../../types'
import {getTabParamsKey} from '../../../utils/tabs'

import {projectTab} from './ProjectPage.slices'

export const changeProjectTab =
  (projectId?: ProjectId): ((next: TabId | null) => AppThunk<void>) =>
  next =>
  (dispatch, getState) => {
    const state = getState()
    const tabParamsKey = getTabParamsKey({projectId})
    dispatch(
      projectTab.actions.change(
        !projectId || tabExists(state, tabParamsKey, next)
          ? next
          : getDefaultProjectTab(state, projectId),
      ),
    )
  }
