import {Tab, Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import {skipToken} from '@reduxjs/toolkit/query'
import classNames from 'classnames'
import {memo, Suspense, useCallback, useEffect} from 'react'

import {type Agent, restApi} from '../../../../../../../services/rest'
import type {TabId} from '../../../../../../../types'
import {toTabId} from '../../../../../../../types'
import Plugin from '../../../../../../common/Plugin/Plugin'
import BuildLogTab from '../../../../../../packages/BuildLog/BuildLogTab/BuildLogTab.container'
import AgentBadgeAgentIncompatibilityReasons from '../../../../components/Badges/AgentBadge/AgentBadgeAgentIncompatibilityReasons'
import {usePipelineDebugArg} from '../../../../PipelineRunPage/PipelineRunPage.hooks'
import styles from '../DebugPanel.module.css'

import {useJobAgentCompatibility} from './DebugPanelContent.hooks'

export const debugTabs = {
  BUILD_LOG: toTabId('buildLog') as TabId,
  TERMINAL: toTabId('terminal') as TabId,
}

type Props = {
  selectedJobId?: string | null
  selectedTab: TabId
  onTabChange: (key: TabId) => void
}

function DebugPanelContent({selectedJobId, selectedTab, onTabChange}: Props) {
  const arg = usePipelineDebugArg()
  const {selectedJob} = restApi.endpoints.getBuildNormalized.useQuery(
    selectedJobId ? arg : skipToken,
    {
      selectFromResult: ({data}) => {
        const run = data?.entities?.builds?.[data?.result!]
        const selectedJob = run?.['snapshot-dependencies']?.build?.find(
          build => build.id === Number(selectedJobId),
        )
        return {
          selectedJob,
        }
      },
    },
  )
  const agentConnected = selectedJob?.agent?.connected

  const {pipelineSettingJobId, isShowNoCompatibleAgent, incompatibilityAgents} =
    useJobAgentCompatibility(selectedJob)

  const openTerminal = useCallback((id?: number | null, agent?: Agent) => {
    if (agent?.connected) {
      const openTerminalEvent = new CustomEvent('open-terminal', {
        detail: {
          buildId: String(id),
          agentId: agent.id,
          isDebug: true,
        },
      })
      window.dispatchEvent(openTerminalEvent)
    }
  }, [])

  const onTabSelect = useCallback(
    (key: string) => {
      const agent = selectedJob?.agent
      openTerminal(selectedJob?.id, agent)
      onTabChange(key)
    },
    [onTabChange, openTerminal, selectedJob?.agent, selectedJob?.id],
  )

  useEffect(() => {
    onTabChange(debugTabs.BUILD_LOG)
  }, [onTabChange, selectedJob?.agent?.connected])

  return (
    <div className={styles.wrapper}>
      <div className={styles.header}>
        <Tabs selected={selectedTab} className={styles.tabs} onSelect={onTabSelect}>
          <Tab id={debugTabs.BUILD_LOG} className={styles.tab} title={'Build Log'} />
          {agentConnected ? (
            <Tab
              id={debugTabs.TERMINAL}
              className={styles.tab}
              title={
                <>
                  <SvgIcon icon={'terminal'} className={styles.icon} />
                  {'Terminal'}
                </>
              }
            />
          ) : null}
        </Tabs>
      </div>
      <div className={styles.container}>
        {isShowNoCompatibleAgent && (
          <div className={styles.incompatibilityWarning}>
            {'No compatible agents which can run this job'}
            <AgentBadgeAgentIncompatibilityReasons
              jobId={pipelineSettingJobId}
              incompatibilityAgents={incompatibilityAgents}
            />
          </div>
        )}
        {selectedTab === debugTabs.BUILD_LOG && selectedJob?.id ? (
          <Suspense>
            <BuildLogTab buildId={selectedJob.id} />
          </Suspense>
        ) : null}
        <Plugin
          className={classNames(styles.pluginWrapper, {
            [styles.selected]: selectedTab === debugTabs.TERMINAL && agentConnected,
          })}
          placeId={PlaceId.SAKURA_DEBUG_PANEL}
        />
      </div>
    </div>
  )
}

export default memo(DebugPanelContent)
