import {useEffect, useMemo} from 'react'
import type {EntryPoint, EntryPointProps, PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import type {LoaderFunctionArgs} from 'react-router'
import {useLocation, useNavigate} from 'react-router'

import type {usePermissionQuery} from '../../hooks/__generated__/usePermissionQuery.graphql'
import {useSetUserProperty} from '../../hooks/useSetUserProperty'
import {getHrefWithQueryParams} from '../../routes'
import {trackEvent} from '../../statistics/statistics.lazy'
import type {PreloadedEntryPoints} from '../../types/entryPoints'
import {getPropertyFromList} from '../../utils/getProperty'
import {queryToObject} from '../../utils/queryParams'
import {UserProperties} from '../../utils/userProperties'
import version from '../../utils/version'
import type {AgentDomainBreadcrumbsComponent} from '../common/AgentDomainBreadcrumbs/AgentDomainBreadcrumbs'
import type {BuildDetailsContentEntryPoint} from '../common/Builds/BuildDetails/BuildDetailsContent/BuildDetailsContent.entryPoint'
import type {OverviewBreadcrumbsComponent} from '../common/OverviewBreadcrumbs/OverviewBreadcrumbs'
import {SWITCH_TO_SAKURA_PARAM} from '../common/ToggleSakuraUI/ToggleSakuraUI.utils'
import type {AgentsSidebarEntryPoint} from '../pages/AgentsPages/AgentsSidebar/AgentsSidebar.entryPoint'
import type {PipelinesBreadcrumbsComponent} from '../pages/PipelinesPages/components/PipelinesBreadcrumbs/PipelinesBreadcrumbs'

import type {AppContainerQuery as AppContainerQueryType} from './__generated__/AppContainerQuery.graphql'
import App from './App'
import {appContainerQuery} from './App.queries'
import type {PipelinesSidebarContentEntryPoint} from './SidebarPanel/SidebarPanelContent/PipelinesSidebar/PipelinesSidebarContent/PipelinesSidebarContent.entryPoint'
import type {ProjectsSidebarEntryPoint} from './SidebarPanel/SidebarPanelContent/ProjectsSidebar/ProjectsSidebar.entryPoint'
import type {QueueSidebarEntryPoint} from './SidebarPanel/SidebarPanelContent/QueueSidebar/QueueSidebar.entryPoint'

type Props = {
  query: PreloadedQuery<AppContainerQueryType>
  entryPoints: PreloadedEntryPoints<AppNestedEntryPoints>
}

function AppContainer({query, entryPoints}: Props) {
  const location = useLocation()
  const navigate = useNavigate()

  useEffect(() => {
    trackEvent({name: 'page.open', groupId: 'page.events.group'})
  }, [])

  const {user = null} = usePreloadedQuery(appContainerQuery, query)

  const isFirstTimeSakuraUI =
    getPropertyFromList(UserProperties.HAS_SEEN_EXPERIMENTAL_OVERVIEW, user?.properties) !== 'true'
  const lastTimeSeenSakuraUIVersion = getPropertyFromList(
    UserProperties.LAST_SEEN_SAKURA_UI_VERSION,
    user?.properties,
  )

  const setUserProperty = useSetUserProperty(user?.id)
  useEffect(() => {
    const {search} = location
    const paramsObject = queryToObject(search)

    if (paramsObject.hasOwnProperty(SWITCH_TO_SAKURA_PARAM)) {
      setUserProperty(UserProperties.USE_EXPERIMENTAL_OVERVIEW, 'true')
      navigate(
        getHrefWithQueryParams(location, null, params => ({
          ...params,
          enableSakuraByDefault: null,
        })),
        {replace: true, preventScrollReset: true},
      )
    }
  }, [setUserProperty, location, navigate])

  useEffect(() => {
    if (
      lastTimeSeenSakuraUIVersion === undefined ||
      (typeof lastTimeSeenSakuraUIVersion === 'string' &&
        lastTimeSeenSakuraUIVersion !== version.full)
    ) {
      setUserProperty(UserProperties.LAST_SEEN_SAKURA_UI_VERSION, version.full)
    }
  }, [setUserProperty, lastTimeSeenSakuraUIVersion])

  useEffect(() => {
    if (isFirstTimeSakuraUI) {
      setUserProperty(UserProperties.HAS_SEEN_EXPERIMENTAL_OVERVIEW, 'true')
    }
  }, [setUserProperty, isFirstTimeSakuraUI])

  return useMemo(() => <App userKey={user} entryPoints={entryPoints} />, [entryPoints, user])
}

export type AppQueries = {
  main: AppContainerQueryType
  canCreateSubproject?: usePermissionQuery // preload for early rendering
}

export type BreadcrumbsComponent =
  | AgentDomainBreadcrumbsComponent
  | OverviewBreadcrumbsComponent
  | PipelinesBreadcrumbsComponent

export type AppNestedEntryPoints = {
  buildDetailsContent?: typeof BuildDetailsContentEntryPoint
  projectsSidebar?: typeof ProjectsSidebarEntryPoint
  queueSidebar?: typeof QueueSidebarEntryPoint
  agentsSidebar?: typeof AgentsSidebarEntryPoint
  pipelinesSidebarContent?: typeof PipelinesSidebarContentEntryPoint
  breadcrumbs?: EntryPoint<BreadcrumbsComponent, LoaderFunctionArgs>
}

export default function AppOuterContainer({
  queries,
  entryPoints,
}: EntryPointProps<AppQueries, AppNestedEntryPoints, {}, {}>) {
  return <AppContainer query={queries.main} entryPoints={entryPoints} />
}
export type AppOuterContainerComponent = typeof AppOuterContainer
