import Shortcuts from '@jetbrains/ring-ui-built/components/shortcuts/shortcuts'
import classNames from 'classnames'
import {Resizable} from 're-resizable'

import {
  COLLAPSED_SIDEBAR_WIDTH,
  MIN_NON_COLLAPSED_SIDEBAR_WIDTH,
  RESIZABLE_ENABLE_CONFIG,
  RESIZABLE_HANDLE_CLASSES,
} from './SidebarPanel.consts'
import {useSidebarPanel} from './SidebarPanel.hooks'
import type {Props} from './SidebarPanel.types'
import {getSidebarSize} from './SidebarPanel.utils'
import SidebarPanelContent from './SidebarPanelContent/SidebarPanelContent'

import styles from './SidebarPanel.module.css'

function SidebarPanel(props: Props) {
  const {
    ref,
    shortcutsScope,
    shortcutsMap,
    sidebarCollapsed,
    sidebarFixed,
    sidebarOverlayMode,
    sidebarTopOffset,
    sidebarHeight,
    sidebarLeftOffset,
    calculatedSidebarWidth,
    maxSidebarWidth,
    onResize,
    onResizeStop,
  } = useSidebarPanel(props)

  return (
    <>
      <Shortcuts map={shortcutsMap} scope={shortcutsScope} />
      <div
        ref={ref}
        className={classNames(styles.sidebar, {
          [styles.fixed]: sidebarFixed,
          [styles.overlay]: !sidebarCollapsed && sidebarOverlayMode,
          [styles.collapsed]: sidebarCollapsed,
        })}
        data-test="sidebar"
        style={{
          top: sidebarFixed ? sidebarTopOffset : undefined,
          left: sidebarFixed ? sidebarLeftOffset : undefined,
          height: sidebarHeight,
        }}
      >
        <Resizable
          size={getSidebarSize(calculatedSidebarWidth)}
          minWidth={
            !sidebarOverlayMode ? MIN_NON_COLLAPSED_SIDEBAR_WIDTH : COLLAPSED_SIDEBAR_WIDTH - 1
          }
          maxWidth={Math.round(maxSidebarWidth)}
          enable={RESIZABLE_ENABLE_CONFIG}
          onResize={onResize}
          onResizeStop={onResizeStop}
          handleClasses={RESIZABLE_HANDLE_CLASSES}
        >
          <SidebarPanelContent
            className={styles.content}
            width={calculatedSidebarWidth - 1}
            projectsSidebarEntryPoint={props.projectsSidebarEntryPoint}
            queueSidebarEntryPoint={props.queueSidebarEntryPoint}
            agentsSidebarEntryPoint={props.agentsSidebarEntryPoint}
            pipelinesSidebarContentEntryPoint={props.pipelinesSidebarContentEntryPoint}
          />
        </Resizable>
      </div>
    </>
  )
}

export default SidebarPanel
