import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo, useCallback, useEffect, useMemo, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import {useBooleanQueryParamState} from '../../../../../../hooks/routes'
import HelpDetails from '../../../../../common/HelpDetails/HelpDetails'
import {resetPageFullLog} from '../../../../../packages/BuildLog/BuildLogTab/BuildLogTab.actions'
import {PipelinesTarget, PipelinesTargetContext} from '../../../contexts/targetContext'
import {usePipelineId} from '../../../hooks/pipeline'
import {useDebugJobIdMap} from '../../EditPipelinePage.hooks'
import {debug} from '../../slices/EditPipelinePage.slices'

import DebugJobTabs from './DebugJobTabs/DebugJobTabs'
import DebugPanelContent, {debugTabs} from './DebugPanelContent/DebugPanelContent'
import DebugPopup from './DebugPopup/DebugPopup'

import styles from './DebugPanel.module.css'

type Props = {
  onExpandToggle: (expanded: boolean) => void
}

function DebugPanel({onExpandToggle}: Props) {
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const expanded = useAppSelector(state => state.pipelines.debug[pipelineId]?.isPanelExpanded)
  const runId = useAppSelector(state => state.pipelines.debug[pipelineId]?.runId)
  const [selectedJobId, setSelectedJobId] = useState<string | null | undefined>(null)
  const [selectedTab, setSelectedTab] = useState(debugTabs.BUILD_LOG)

  const [isJobDetailsFullscreen, setIsJobDetailsFullscreen] = useBooleanQueryParamState(
    'jobDetailsFullscreen',
    false,
  )

  const debugJobIdMap = useDebugJobIdMap()
  const jobs = useMemo(() => [...debugJobIdMap.values()], [debugJobIdMap])

  useEffect(() => {
    setSelectedTab(debugTabs.BUILD_LOG)
  }, [runId])

  useEffect(() => {
    const currentJob = jobs.find(job => String(job) === selectedJobId)
    if (!currentJob && jobs.length) {
      setSelectedJobId(String(jobs[0]))
    }
  }, [selectedJobId, jobs])

  const onExpand = useCallback(() => {
    const isExpaned = !expanded
    dispatch(debug.actions.expandPanel({pipelineId, expanded: !expanded}))
    onExpandToggle(isExpaned)
  }, [dispatch, expanded, onExpandToggle, pipelineId])

  const onClose = useCallback(() => {
    dispatch(debug.actions.toggleOpenPanel({pipelineId, open: false}))
  }, [dispatch, pipelineId])

  const onDialogOpen = useCallback(() => {
    setSelectedTab(debugTabs.BUILD_LOG)
    setIsJobDetailsFullscreen(!isJobDetailsFullscreen, true)
  }, [isJobDetailsFullscreen, setIsJobDetailsFullscreen])

  const onDialogClose = useCallback(() => {
    setSelectedTab(debugTabs.BUILD_LOG)
    setIsJobDetailsFullscreen(false, true)
  }, [setIsJobDetailsFullscreen])

  const onTabChange = useCallback((key: string) => {
    setSelectedTab(key)
  }, [])

  const onJobSelect = useCallback(
    (key: string) => {
      if (key !== selectedJobId) {
        dispatch(resetPageFullLog())
        setSelectedJobId(key)
        setSelectedTab(debugTabs.BUILD_LOG)
      }
    },
    [dispatch, selectedJobId],
  )

  const content = useMemo(() => {
    if (!jobs.length) {
      return (
        <div className={styles.loader}>
          <LoaderInline>{'Loading...'}</LoaderInline>
        </div>
      )
    }

    return (
      <DebugPanelContent
        selectedJobId={selectedJobId}
        selectedTab={selectedTab}
        onTabChange={onTabChange}
      />
    )
  }, [jobs, onTabChange, selectedJobId, selectedTab])

  return (
    <>
      <div className={styles.panel}>
        <div className={styles.header}>
          <div className={styles.heading}>
            <span className={styles.title}>{'Debug'}</span>
            <HelpDetails acnhorClassName={styles.help}>
              {'Debugger allows you to dry run isolated jobs without launching an entire Pipeline'}
            </HelpDetails>
            {expanded && (
              <DebugJobTabs jobs={jobs} selectedJobId={selectedJobId} onJobSelect={onJobSelect} />
            )}
          </div>
          <div className={styles.actions}>
            <IconButton icon={'expand-all'} title={'Enter full screen'} onClick={onDialogOpen} />
            <IconButton
              icon={expanded ? 'double-chevron-left' : 'double-chevron-right'}
              title={expanded ? 'Collapse' : 'Expand'}
              iconClassName={styles.chevron}
              onClick={onExpand}
            />
            <IconButton icon={'close'} title={'Close'} onClick={onClose} />
          </div>
        </div>
        <PipelinesTargetContext.Provider value={PipelinesTarget.JOB_DEBUG_PANEL}>
          {!isJobDetailsFullscreen ? content : null}
        </PipelinesTargetContext.Provider>
      </div>
      <PipelinesTargetContext.Provider value={PipelinesTarget.JOB_DEBUG_POPUP}>
        <DebugPopup
          jobs={jobs}
          selectedJobId={selectedJobId}
          onJobSelect={onJobSelect}
          content={content}
          onClose={onDialogClose}
        />
      </PipelinesTargetContext.Provider>
    </>
  )
}

export default memo(DebugPanel)
