import {memo, Suspense, useMemo} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import {useBuildId} from '../../../../../hooks/routes'
import {getBuildLocator} from '../../../../../rest/locators'
import {getBuild, getFullPath} from '../../../../../selectors'
import type {FullPath, NormalizedBuild} from '../../../../../types'
import ServiceMessage from '../../../../common/ServiceMessage/ServiceMessage'

import type {CompareBuildAlertQuery} from './__generated__/CompareBuildAlertQuery.graphql'
import CompareBuildAlertButtons from './CompareBuildAlert.buttons'
import type {CompareBuildAlertProps} from './CompareBuildAlert.types'

import styles from './CompareBuildAlert.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const query = graphql`
  query CompareBuildAlertQuery($buildLocator: String!, $skip: Boolean!) {
    build(buildLocator: $buildLocator) @skip(if: $skip) {
      buildTypeId
      number
    }
  }
`

function CompareAlertContent({
  sourceBuildId,
  showChooseBuildDialog,
  resetSourceId,
}: CompareBuildAlertProps) {
  const pageBuildId = useBuildId()
  const build: NormalizedBuild | null | undefined = useAppSelector(state =>
    getBuild(state, sourceBuildId),
  )
  const data = useLazyLoadQuery<CompareBuildAlertQuery>(query, {
    buildLocator: getBuildLocator(sourceBuildId),
    skip: build != null,
  })
  const buildTypeId = build?.buildType ?? data.build?.buildTypeId
  const buildNumberString = build?.number ?? data.build?.number
  const buildPath: FullPath | null | undefined = useAppSelector(state =>
    buildTypeId != null
      ? getFullPath(state, {
          nodeType: 'bt',
          id: buildTypeId,
        })
      : null,
  )

  const buildPathString = buildPath?.map(i => i.name).join(' / ')
  const addThisBuild = pageBuildId != null && pageBuildId !== sourceBuildId

  return (
    <>
      <h3 className={styles.title}>
        {addThisBuild ? 'Add this build to comparison?' : 'This Build is selected for comparison'}
      </h3>
      <p>
        {buildPathString != null && buildNumberString != null
          ? `The build ${buildPathString} / #${buildNumberString} is currently selected for\u00A0comparison.`
          : `The first build has ${addThisBuild ? 'already' : ''} been selected for comparison.`}
        <br />
        {addThisBuild
          ? 'Would you like to compare it to the current build?'
          : 'Add the second build now or via its Actions menu.'}
      </p>
      <CompareBuildAlertButtons
        addThisBuild={addThisBuild}
        sourceBuildId={sourceBuildId}
        onCloseRequest={resetSourceId}
        showChooseBuildDialog={showChooseBuildDialog}
        pageBuildId={pageBuildId}
      />
    </>
  )
}
CompareAlertContent.displayName = 'CompareAlertContent'

function CompareBuildAlert({
  sourceBuildId,
  showChooseBuildDialog,
  resetSourceId,
}: CompareBuildAlertProps) {
  return useMemo(
    () =>
      sourceBuildId != null ? (
        <ServiceMessage icon="compare" closeable={false} descriptionClassName={styles.description}>
          <Suspense>
            <CompareAlertContent
              sourceBuildId={sourceBuildId}
              showChooseBuildDialog={showChooseBuildDialog}
              resetSourceId={resetSourceId}
            />
          </Suspense>
        </ServiceMessage>
      ) : null,
    [sourceBuildId, showChooseBuildDialog, resetSourceId],
  )
}

export default memo(CompareBuildAlert)
