import memoize from '@jetbrains/ring-ui-built/components/global/memoize'
import type {Size} from 're-resizable'

import {MAX_PANEL_HEIGHT, MIN_PANEL_HEIGHT} from './ToolPanelFooter.consts'

export function getDefaultPanelHeightByWindowHeight(): number {
  const windowHeight: number = window.innerHeight

  /* eslint-disable @typescript-eslint/no-magic-numbers */
  if (windowHeight <= 720) {
    return MIN_PANEL_HEIGHT
  }

  if (windowHeight >= 1440) {
    return MAX_PANEL_HEIGHT
  }

  return (windowHeight - 1080) * 0.4 + 356
  /* eslint-enable @typescript-eslint/no-magic-numbers */
}

export const getMaxPanelHeight: () => number = () => {
  const windowHeight: number = window.innerHeight

  /* eslint-disable @typescript-eslint/no-magic-numbers */
  if (windowHeight / MAX_PANEL_HEIGHT >= 1.5) {
    return MAX_PANEL_HEIGHT
  }
  /* eslint-enable @typescript-eslint/no-magic-numbers */

  return MIN_PANEL_HEIGHT
}

export const getPanelSize: (height: number) => Size = memoize((height: number) => ({
  height: `${height}px`,
  width: '100%',
}))
