import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import classNames from 'classnames'
import type * as React from 'react'
import {Suspense} from 'react'

import Icon from '../Icon/Icon'

import styles from './HelpDetails.module.css'

type Props = {
  className?: string
  acnhorClassName?: string
  children?: React.ReactNode
  onHover?: (state: boolean) => void
}

function HelpDetails({className, acnhorClassName, onHover, children}: Props) {
  const hoverIconHandler = (state: boolean) => () => onHover?.(state)
  const clickIconHandler = (event: React.MouseEvent) => {
    event.stopPropagation()
    event.preventDefault()
  }

  return (
    <Dropdown
      className={className}
      anchor={() => (
        <div
          role="presentation"
          onClick={clickIconHandler}
          onMouseEnter={hoverIconHandler(true)}
          onMouseLeave={hoverIconHandler(false)}
        >
          <Icon
            name="info"
            active="false"
            title=""
            className={classNames(styles.anchor, acnhorClassName)}
          />
        </div>
      )}
      hoverMode
    >
      <Popup className={styles.detailsPopup}>
        <Suspense>{children}</Suspense>
      </Popup>
    </Dropdown>
  )
}

export default HelpDetails
