import type {PlaceId} from '@jetbrains/teamcity-ui'
import pluginRegistry from '@jetbrains/teamcity-ui/dist/plugin/registry'
import type {ReactNode} from 'react'
import {useEffect, useState} from 'react'

type Props = {
  children: ReactNode
  placeId: PlaceId
}

function PluginWrapper({children, placeId}: Props) {
  const [hasPlugins, setHasPlugins] = useState(false)

  useEffect(() => {
    const udpateRegistyHandler = () => {
      const plugins = pluginRegistry.searchByPlaceId(placeId)
      setHasPlugins(Array.isArray(plugins) ? plugins.length > 0 : plugins != null)
    }

    pluginRegistry.subscribe(udpateRegistyHandler)
    return () => pluginRegistry.unsubscribe(udpateRegistyHandler)
  }, [placeId])

  return hasPlugins ? children : null
}
export default PluginWrapper
