import {changeBuildTypeTab, changeBuildTab} from '../actions'
import {
  getShowLog,
  getLinesState,
  getFocusLine,
  getExpandAll,
  getLogFilter,
} from '../components/packages/BuildLog/BuildLog.selectors'
import {setShowLog} from '../components/packages/BuildLog/BuildLogPopup/BuildLogPopup.actions'
import {
  setLinesState,
  setFocusLine,
  setExpandAll,
} from '../components/packages/BuildLog/BuildLogTab/BuildLogTab.actions'
import {setLogFilter} from '../components/packages/BuildLog/FullBuildLog/FullBuildLog.actions'
import {changeProjectTab} from '../components/pages/ProjectPage/ProjectPage.actions'
import {getCurrentBuildTypeTab, getCurrentBuildTab, getCurrentProjectPageTab} from '../selectors'

import QuerySync, {Param} from './QuerySync'

export default function QuerySyncContainer() {
  return (
    <QuerySync>
      <Param
        name="buildTypeTab"
        action={changeBuildTypeTab}
        selector={getCurrentBuildTypeTab}
        defaultValue={null}
      />
      <Param
        name="buildTab"
        action={changeBuildTab}
        selector={getCurrentBuildTab}
        defaultValue={null}
      />
      <Param
        name="projectTab"
        action={changeProjectTab()}
        selector={getCurrentProjectPageTab}
        defaultValue={null}
      />
      <Param name="showLog" action={setShowLog} selector={getShowLog} defaultValue={null} />
      <Param
        name="focusLine"
        action={setFocusLine}
        selector={getFocusLine}
        defaultValue={null}
        stringToValue={parseInt}
      />
      <Param
        name="linesState"
        action={setLinesState}
        selector={getLinesState}
        defaultValue={null}
      />
      <Param
        name="expandAll"
        action={setExpandAll}
        selector={getExpandAll}
        defaultValue={false}
        stringToValue={param => param === 'true'}
      />
      <Param name="logFilter" action={setLogFilter} selector={getLogFilter} defaultValue={null} />
    </QuerySync>
  )
}
