import * as React from 'react'
import {memo, useMemo, Suspense} from 'react'
import {graphql, useFragment} from 'react-relay'
import {useLocation} from 'react-router'

import QuerySyncContainer from '../../containers/QuerySyncContainer'
import type {currentUserKeyFragment$key} from '../../contexts/__generated__/currentUserKeyFragment.graphql'
import {currentUserKeyFragment} from '../../contexts/currentUserKey'
import {useAppSelector} from '../../hooks/react-redux'
import {useQueryParams} from '../../hooks/routes'
import {getEditUrlFormats, isPipelinesEditScreen, isScreenWithSidebar} from '../../routes'
import type {PreloadedEntryPoints} from '../../types/entryPoints'
import CurrentUserKeyProvider from '../common/CurrentUserKeyProvider/CurrentUserKeyProvider'
import {ProjectsTreeContext} from '../common/ProjectsTree/ProjectsTree.context'
import BuildLogPopup from '../packages/BuildLog/BuildLogPopup/BuildLogPopup.container'

import type {AppFragment$key} from './__generated__/AppFragment.graphql'
import type {AppNestedEntryPoints} from './App.container'
import Header from './Header/Header.lazy'
import MainPanel from './MainPanel/MainPanel'
import SidebarPanel from './SidebarPanel/SidebarPanel'
import {COLLAPSED_SIDEBAR_WIDTH} from './SidebarPanel/SidebarPanel.consts'
import ToolPanelFooter from './ToolPanelFooter/ToolPanelFooter'

import './App.module.css'

const Hints: React.ComponentType = React.lazy(
  () =>
    import(
      /* webpackChunkName: "Hints" */
      '../packages/Hints/Hints'
    ),
)

const Feedback: React.ComponentType = React.lazy(
  () =>
    import(
      /* webpackChunkName: "Feedback" */
      '../pages/PipelinesPages/components/Feedback/Feedback'
    ),
)

const appFragment = graphql`
  fragment AppFragment on User {
    ...currentUserKeyFragment
    ...AllUserSelectFragment
  }
`

type Props = {
  userKey: AppFragment$key | null
  entryPoints: PreloadedEntryPoints<AppNestedEntryPoints>
}

function App({userKey, entryPoints}: Props) {
  const location = useLocation()
  const user = useFragment(appFragment, userKey)
  const currentUserKey = useFragment<currentUserKeyFragment$key>(currentUserKeyFragment, user)

  const withSidebar = isScreenWithSidebar(location.pathname)
  const isSidebarPinned = useAppSelector(state => state.sidebarSettings.pinned)
  const isPinDisabled = useAppSelector(state => state.sidebarSettings.pinDisabled)
  const toolPanelFooterHeight = useAppSelector(state => state.toolPanelFooter.height)
  const [sidebarPanelWidth, setSidebarPanelWidth] = React.useState(0)
  const isSidebarOverlayMode = !isSidebarPinned || isPinDisabled

  const queryParams = useQueryParams()
  const isEditMode = isPipelinesEditScreen(queryParams)
  const contextValue = useMemo(
    () => ({
      isPopup: false,
      isAdmin: isEditMode,
      ...(isEditMode ? {...getEditUrlFormats()} : {}),
    }),
    [isEditMode],
  )

  return (
    <CurrentUserKeyProvider userKey={currentUserKey}>
      <Header />
      {withSidebar ? (
        <ProjectsTreeContext.Provider value={contextValue}>
          <SidebarPanel
            offsetBottom={toolPanelFooterHeight}
            onResize={setSidebarPanelWidth}
            projectsSidebarEntryPoint={entryPoints.projectsSidebar}
            queueSidebarEntryPoint={entryPoints.queueSidebar}
            agentsSidebarEntryPoint={entryPoints.agentsSidebar}
            pipelinesSidebarContentEntryPoint={entryPoints.pipelinesSidebarContent}
          />
        </ProjectsTreeContext.Provider>
      ) : null}
      {(!withSidebar || sidebarPanelWidth > 0) && (
        <MainPanel
          offsetBottom={toolPanelFooterHeight}
          offsetLeft={
            withSidebar && isSidebarOverlayMode ? COLLAPSED_SIDEBAR_WIDTH : sidebarPanelWidth
          }
          breadcrumbsEntryPoint={entryPoints.breadcrumbs}
        />
      )}
      <ToolPanelFooter />
      <QuerySyncContainer />
      <BuildLogPopup />
      <Hints />

      <Suspense>
        <Feedback />
      </Suspense>
    </CurrentUserKeyProvider>
  )
}

export default memo(App)
