import {createDraft} from 'immer'

import {useCallback, useEffect, useMemo, useState} from 'react'
import {useSearchParams} from 'react-router'

import {useAppSelector, useAppStore} from '../../../../hooks/react-redux'
import {emptyObject} from '../../../../utils/empty'
import {useJobId} from '../EditPipelinePage/EditPipelinePage.hooks'
import {
  getDrafParamtersChangesWatcher,
  getResolvedSettings,
  getRunsOn,
} from '../EditPipelinePage/EditPipelinePage.selectors'
import {isSelfHostedRunsOn} from '../EditPipelinePage/EditPipelinePage.utils'
import {pipelinesApi} from '../services/pipelinesApi'
import type {NewPipeline} from '../services/pipelinesApi.types'
import {isPipelineCompatibilityAgentsEnabled} from '../utils/featureToggles'

import {usePipelineId} from './pipeline'

function useMapAgentCompatibilities(id?: string) {
  const selectedJobId = useJobId() ?? ''
  const currentJobId = id ?? selectedJobId
  const pipelineId = usePipelineId()
  const drafParamtersChanges = useAppSelector(state =>
    getDrafParamtersChangesWatcher(state, pipelineId),
  )
  const [editStepId, setEditStepId] = useState<string | null>(null)
  const currentJobAgent = useAppSelector(getRunsOn(currentJobId, pipelineId))
  const [searchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const {getState} = useAppStore()
  const resolvedPipelineSettings = useCallback(
    () => (getResolvedSettings(getState(), pipelineId) ?? emptyObject) as NewPipeline,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [getState, currentJobAgent, pipelineId, currentJobId],
  )
  const [loadAgentCompatibilities, {jobMapAgentCompatibilities, isAgentCompatibilitiesLoading}] =
    pipelinesApi.endpoints.jobMapAgentCompatibilities.useLazyQuery({
      selectFromResult: ({data, isLoading}) => ({
        jobMapAgentCompatibilities: data,
        isAgentCompatibilitiesLoading: isLoading,
      }),
    })
  const getCompatibilitieAgentsByJobId = useCallback(
    (value: string) => jobMapAgentCompatibilities?.[value]?.compatibilities,
    [jobMapAgentCompatibilities],
  )
  const cloudImageAgentCompatibilities = useMemo(
    () =>
      getCompatibilitieAgentsByJobId(currentJobId)?.filter(
        ({agent}) => agent.type === 'CLOUD_IMAGE',
      ),
    [currentJobId, getCompatibilitieAgentsByJobId],
  )
  const fetchAgentCompatibilities = useCallback(
    (isSelfHosted?: boolean) => {
      if (isSelfHosted || isPipelineCompatibilityAgentsEnabled) {
        loadAgentCompatibilities({
          pipelineId,
          body: createDraft(resolvedPipelineSettings()),
        })
      }
    },
    [loadAgentCompatibilities, pipelineId, resolvedPipelineSettings],
  )
  const getIsCurrentAgentIncompatibleByJobId = useCallback(
    (jobId: string) => {
      const jobAgent = resolvedPipelineSettings().settings?.jobs?.[jobId]?.['runs-on']

      if (jobAgent) {
        const isSelfHosted = isSelfHostedRunsOn(jobAgent)
        const imageAgentCompatibilities = getCompatibilitieAgentsByJobId(jobId)

        if (isSelfHosted && imageAgentCompatibilities?.length != null) {
          const foundAgentCompatible = imageAgentCompatibilities.find(({compatible}) => compatible)

          return !foundAgentCompatible
        }

        if (jobAgent && imageAgentCompatibilities?.length != null) {
          const foundAgentCompatible = imageAgentCompatibilities.find(
            ({agent}) => agent.name === jobAgent,
          )?.compatible

          return foundAgentCompatible === false
        }
      }

      return false
    },
    [getCompatibilitieAgentsByJobId, resolvedPipelineSettings],
  )
  const isCurrentAgentIncompatible = useMemo(
    () => currentJobId && getIsCurrentAgentIncompatibleByJobId(currentJobId),
    [currentJobId, getIsCurrentAgentIncompatibleByJobId],
  )

  useEffect(() => {
    if (searchParamsObject?.step) {
      setEditStepId(searchParamsObject.step)
    }
    if (
      isPipelineCompatibilityAgentsEnabled &&
      ((!searchParamsObject?.step && editStepId) || !searchParamsObject?.step)
    ) {
      fetchAgentCompatibilities()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentJobAgent, drafParamtersChanges, searchParamsObject.step])

  return {
    getCompatibilitieAgentsByJobId,
    fetchAgentCompatibilities,
    cloudImageAgentCompatibilities,
    isAgentCompatibilitiesLoading,
    isCurrentAgentIncompatible,
    getIsCurrentAgentIncompatibleByJobId,
  }
}

export default useMapAgentCompatibilities
