import {withProps} from 'recompose'

import {connect} from 'react-redux'

import withDialogContainer from '../../../../hocs/withDialogContainer'
import type {State} from '../../../../reducers/types'
import type {LocationProps} from '../../../../routes'
import {withLocation} from '../../../../routes'
import {getExtensionEndpoint, getIsSakuraUI} from '../../../../selectors'
import {DialogType} from '../../../../types'
import {queryToObject} from '../../../../utils/queryParams'

import CompareBuildDialog from './CompareBuildDialog'

const mapStateToProps = (state: State) => ({
  endpoint: getExtensionEndpoint(state, 'builds-diff')?.endpoint,
  isSakuraUI: getIsSakuraUI(state),
})

export default withLocation(
  withProps(({location}: LocationProps) => ({
    currentTab: queryToObject(location?.search).tab,
  }))(withDialogContainer(DialogType.COMPARE)(connect(mapStateToProps)(CompareBuildDialog))),
)
