import {skipToken} from '@reduxjs/toolkit/query'
import {memo} from 'react'

import {getBuildStatusIconFromBuild} from '../../../../../../../../selectors'
import {restApi} from '../../../../../../../../services/rest'
import JobIconStatus from '../../../../../components/JobIconStatus/JobIconStatus'
import {usePipelineDebugArg} from '../../../../../PipelineRunPage/PipelineRunPage.hooks'
import styles from '../../DebugPanel.module.css'

type Props = {
  jobId?: number | null
}

function DebugJobTab({jobId}: Props) {
  const arg = usePipelineDebugArg()
  const {job} = restApi.endpoints.getBuildNormalized.useQuery(jobId ? arg : skipToken, {
    selectFromResult: ({data}) => {
      const run = data?.entities?.builds?.[data?.result!]
      const currentJob = run?.['snapshot-dependencies']?.build?.find(build => build.id === jobId)
      return {
        job: currentJob,
      }
    },
  })

  const title = job?.buildType?.name
  const isFinished = job?.state === 'finished'
  const icon = getBuildStatusIconFromBuild(job, null, false, false, true)

  return (
    <>
      {isFinished && <JobIconStatus className={styles.icon} icon={icon} />}
      {title}
    </>
  )
}

export default memo(DebugJobTab)
