import {memo, useCallback} from 'react'

import {openDialog} from '../../../../actions'
import useStorageSyncValue, {SyncStorageKey} from '../../../../hooks/useStorageSyncValue'
import {DialogType, stringifyId, toBuildId} from '../../../../types'
import CompareBuildDialog from '../CompareBuildDialog/CompareBuildDialog.container'

import {useIsComparable} from './ChooseCompareBuilds.hooks'
import CompareBuildAlert from './CompareBuildAlert/CompareBuildAlert'

import {useAppDispatch} from 'src/hooks/react-redux'

function ChooseCompareBuilds() {
  const isComparable = useIsComparable()
  const [sourceId, setSourceId] = useStorageSyncValue(SyncStorageKey.COMPARE_BUILD_SOURCE)
  const sourceBuildId = sourceId != null ? toBuildId(sourceId) : null
  const dispatch = useAppDispatch()
  const showChooseBuildDialog = useCallback(() => {
    dispatch(openDialog(stringifyId(sourceBuildId), DialogType.COMPARE))
  }, [sourceBuildId, dispatch])
  const resetSourceId = useCallback(() => {
    setSourceId(null)
  }, [setSourceId])

  if (!isComparable || sourceId == null || sourceBuildId == null) {
    return null
  }

  return (
    <>
      <CompareBuildAlert
        sourceBuildId={sourceBuildId}
        showChooseBuildDialog={showChooseBuildDialog}
        resetSourceId={resetSourceId}
      />
      <CompareBuildDialog buildId={sourceBuildId} compareWithId={null} onSelect={resetSourceId} />
    </>
  )
}

export default memo(ChooseCompareBuilds)
