import Link from '@jetbrains/ring-ui-built/components/link/link'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import {Fragment} from 'react'

import SelfHostedCompatibleAgentDialog from '../../../EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobAgentRequirements/SelfHosted/Compatible/SelfHostedCompatibleAgentDialog'
import useBooleanState from '../../../hooks/useBooleanState'
import type {AgentCompatibility} from '../../../services/pipelinesApi.types'

import styles from './AgentBadge.module.css'

type AgentBadgeAgentIncompatibilityReasonsProps = {
  incompatibilityAgents?: AgentCompatibility[]
  jobId?: string
}

function AgentBadgeAgentIncompatibilityReasons({
  incompatibilityAgents,
  jobId,
}: AgentBadgeAgentIncompatibilityReasonsProps) {
  const [
    isShowReasonsIncompatibility,
    clickShowReasonsIncompatibilityButtonHandler,
    clickCloseReasonsIncompatibilityButtonHandler,
  ] = useBooleanState(false)
  const linkToJob = objectToQuery({edit: 'true', job: jobId})
  const runsOnAnchor = '#:~:text=Run on'
  const linkOnEditJob = `?${linkToJob}${runsOnAnchor}`

  return (
    <Fragment>
      <Link
        title={'Show more'}
        aria-label={'Show more'}
        onClick={clickShowReasonsIncompatibilityButtonHandler}
      >
        {'Show more'}
      </Link>
      {isShowReasonsIncompatibility && (
        <SelfHostedCompatibleAgentDialog
          show
          isCloudHosted
          subtitleText={
            <Fragment>
              <Text>
                {
                  'The selected agent is incompatible. Fix compatibility issues from the table below or choose a different agent in job settings. '
                }
              </Text>
              <IconButton
                icon={'new-window'}
                title={'Manage agents'}
                aria-label={'Manage agents'}
                inline
                iconClassName={styles.incompatibilityReasonsJobLinkIcon}
                className={styles.incompatibilityReasonsJobLink}
                href={linkOnEditJob}
                rel="noreferrer"
                childrenLeft
              >
                {'Find a compatible agent'}
              </IconButton>
            </Fragment>
          }
          agents={incompatibilityAgents}
          onCloseAttempt={clickCloseReasonsIncompatibilityButtonHandler}
        />
      )}
    </Fragment>
  )
}

export default AgentBadgeAgentIncompatibilityReasons
