import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'
import {Suspense, memo} from 'react'
import {EntryPointContainer} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'
import {Outlet, ScrollRestoration, useLocation} from 'react-router'

import OneLineDetector from '../../../containers/OneLineDetector'
import {useQueryParam} from '../../../hooks/routes'
import {
  isAgentsScreen,
  isCenteredContentScreen,
  isPipelinesScreen,
  isSakuraUIOnlyScreen,
  matchRoute,
  Routes,
} from '../../../routes'
import {BuildPageTabNamesEnum} from '../../../types'
import Loader from '../../common/Loader/Loader'
import Plugin from '../../common/Plugin/Plugin'
import OpenInClassicUI from '../../common/ToggleSakuraUI/OpenInClassicUI.container'
import ChooseCompareBuilds from '../../pages/CompareBuildsPage/ChooseCompareBuilds/ChooseCompareBuilds'
import {isPipelinesAgentPageEnabled} from '../../pages/PipelinesPages/utils/featureToggles'
import type {BreadcrumbsComponent} from '../App.container'
import BreadcrumbsPanel from '../BreadcrumbsPanel/BreadcrumbsPanel'
import {getContentTopOffset} from '../SidebarPanel/SidebarPanel.utils'

import RedirectAlert from './RedirectAlert/RedirectAlert'
import Version from './Version/Version'

import styles from './MainPanel.module.css'

type Props = {
  offsetBottom?: number
  offsetLeft?: number
  breadcrumbsEntryPoint?: PreloadedEntryPoint<BreadcrumbsComponent>
}

function shouldShowBreadcrumbs(pathname: string) {
  const isCreatePipelineScreen = matchRoute(Routes.CREATE_PIPELINE, pathname)
  const isCreateProjectScreen = matchRoute(Routes.CREATE_PROJECT, pathname)
  const isAddPipelineRepositoryScreen = matchRoute(Routes.ADD_REPOSITORY, location.pathname)

  return !isCreatePipelineScreen && !isCreateProjectScreen && !isAddPipelineRepositoryScreen
}

function MainPanel({offsetBottom = 0, offsetLeft, breadcrumbsEntryPoint}: Props) {
  const location = useLocation()

  const offsetTop = getContentTopOffset()
  const minHeight = `calc(100vh - ${offsetTop}px - ${offsetBottom}px)`
  const style = {
    minHeight,
    marginLeft: offsetLeft || undefined,
    marginBottom: offsetBottom,
  }
  const isPipelines =
    isPipelinesScreen(location.pathname) ||
    (isPipelinesAgentPageEnabled() && isAgentsScreen(location.pathname))
  const buildTab = useQueryParam('buildTab')

  return (
    <main
      id="main-content-tag"
      data-main-panel
      className={classNames(styles.mainPanel, {
        [styles.withBottomPadding]:
          !isPipelines &&
          !(matchRoute(Routes.BUILD, location.pathname) && buildTab === BuildPageTabNamesEnum.LOG),
      })}
      style={style}
    >
      <Plugin placeId={PlaceId.SAKURA_BEFORE_CONTENT} className={styles.beforeContent} />
      {shouldShowBreadcrumbs(location.pathname) && (
        <BreadcrumbsPanel>
          {breadcrumbsEntryPoint && (
            <EntryPointContainer entryPointReference={breadcrumbsEntryPoint} props={{}} />
          )}
        </BreadcrumbsPanel>
      )}
      {!isSakuraUIOnlyScreen(location.pathname) &&
        !(isPipelinesAgentPageEnabled() && isAgentsScreen(location.pathname)) && (
          <OpenInClassicUI />
        )}
      <OneLineDetector
        className={classNames(styles.content, {
          [styles.centered]: isCenteredContentScreen(location.pathname),
        })}
      >
        <Suspense fallback={<Loader data-suspense-fallback />}>
          <div data-main-router className={styles.router}>
            <Outlet />
          </div>
        </Suspense>
      </OneLineDetector>
      <RedirectAlert />
      <ChooseCompareBuilds />
      {process.env.NODE_ENV !== 'test' && <ScrollRestoration />}
      <Version />
    </main>
  )
}

export default memo(MainPanel)
