import * as React from 'react'
import {EntryPointContainer} from 'react-relay'
import {useLocation} from 'react-router'

import {isAgentsScreen, isPipelinesScreen, isQueueScreen} from '../../../../routes'
import {isPipelinesEnabledInExclusiveMode} from '../../../pages/PipelinesPages/utils/featureToggles'

import PipelinesSidebar from './PipelinesSidebar/PipelinesSidebar'
import type {CommonSidebarContentProps, Props} from './SidebarPanelContent.types'

import styles from './SidebarPanelContent.module.css'

function SidebarPanelContent({
  width,
  className,
  projectsSidebarEntryPoint,
  queueSidebarEntryPoint,
  agentsSidebarEntryPoint,
  pipelinesSidebarContentEntryPoint,
}: Props) {
  const location = useLocation()
  const renderContent = () => {
    const commonProps: CommonSidebarContentProps = {
      className: styles.content,
      width,
    }

    if (
      isPipelinesScreen(location.pathname) &&
      isPipelinesEnabledInExclusiveMode() &&
      pipelinesSidebarContentEntryPoint
    ) {
      return (
        <PipelinesSidebar {...commonProps} contentEntryPoint={pipelinesSidebarContentEntryPoint} />
      )
    }

    if (isAgentsScreen(location.pathname) && agentsSidebarEntryPoint) {
      return (
        <EntryPointContainer entryPointReference={agentsSidebarEntryPoint} props={commonProps} />
      )
    }

    if (isQueueScreen(location.pathname) && queueSidebarEntryPoint) {
      return (
        <EntryPointContainer entryPointReference={queueSidebarEntryPoint} props={commonProps} />
      )
    }

    if (projectsSidebarEntryPoint) {
      return (
        <EntryPointContainer
          entryPointReference={projectsSidebarEntryPoint}
          props={{...commonProps, default: true}}
        />
      )
    }

    return null
  }

  return (
    <React.Suspense fallback={<div data-suspense-fallback className={styles.placeholder} />}>
      <div className={className}>{renderContent()}</div>
    </React.Suspense>
  )
}

export default React.memo(SidebarPanelContent)
