import Button from '@jetbrains/ring-ui-built/components/button/button'
import compose from 'lodash/flowRight'
import * as React from 'react'

import withHook from '../../../../hocs/withHook'
import {useQueryParamState, withActiveEntityId} from '../../../../hooks/routes'
import type {LocationProps} from '../../../../routes'
import {withLocation} from '../../../../routes'
import {stringifyId} from '../../../../types'
import type {BuildTypeId, ProjectId, ActiveEntityProps} from '../../../../types'
import ServiceMessage from '../../../common/ServiceMessage/ServiceMessage'

import styles from './RedirectAlert.module.css'

type Props = {
  buildTypeId?: BuildTypeId
  projectId?: ProjectId
  redirectedFrom: string | null | undefined
  show: boolean
  close?: () => unknown
}

const getIdText = ({buildTypeId, projectId}: Props) => {
  if (buildTypeId != null) {
    return `build configuration id "${stringifyId(buildTypeId)}"`
  }

  if (projectId != null) {
    return `project id "${stringifyId(projectId)}"`
  }

  return ''
}

export function RedirectAlert(props: Props) {
  const {close, redirectedFrom, show} = props
  const controls = React.useMemo(
    () => (
      <Button primary onClick={close} className={styles.button}>
        {'OK'}
      </Button>
    ),
    [close],
  )
  return show ? (
    <ServiceMessage title={'Redirected'} onCloseRequest={close} controls={controls}>
      {`Page was redirected to use current ${getIdText(props)} instead of previous one "${
        redirectedFrom ?? ''
      }". Please update your bookmarks.`}
    </ServiceMessage>
  ) : null
}

type State = Readonly<{
  show: boolean
  redirectedFrom?: string | null | undefined
  buildTypeId?: BuildTypeId | null | undefined
  projectId?: ProjectId | null | undefined
}>
type Action =
  | {
      type: 'CLOSE'
    }
  | {
      type: 'REDIRECT'
      redirectedFrom: string
      buildTypeId: BuildTypeId | null | undefined
      projectId: ProjectId | null | undefined
    }
const initialState = {
  show: false,
  redirectedFrom: null,
}

const reducer = (state: State, action: Action) => {
  switch (action.type) {
    case 'CLOSE':
      return !state.show ? state : {...state, show: false}

    case 'REDIRECT':
      const {redirectedFrom, buildTypeId, projectId} = action
      return {...state, redirectedFrom, buildTypeId, projectId, show: true}

    default:
      return state
  }
}

export default compose(
  withActiveEntityId,
  withLocation,
  withHook(({location, buildTypeId, projectId}: ActiveEntityProps & LocationProps) => {
    const [state, dispatch] = React.useReducer(reducer, initialState)
    const close = React.useCallback(
      () =>
        dispatch({
          type: 'CLOSE',
        }),
      [dispatch],
    )
    const [redirectedFromId, setRedirectedFromId] = useQueryParamState('redirectedFromId')
    React.useEffect(() => {
      if (redirectedFromId != null) {
        dispatch({
          type: 'REDIRECT',
          redirectedFrom: redirectedFromId,
          buildTypeId,
          projectId,
        })
        setRedirectedFromId(null)
      } else {
        dispatch({
          type: 'CLOSE',
        })
      } // We only care about changing location.pathname
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [location.pathname])
    return React.useMemo(
      () => ({
        close,
        ...state,
      }),
      [close, state],
    )
  }),
  React.memo,
)(RedirectAlert)
