import {useMemo} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import type {Build} from '../../../../../../../services/rest'
import {BuildStatusType} from '../../../../../../../types'
import {usePipelineId} from '../../../../hooks/pipeline'
import useMapAgentCompatibilities from '../../../../hooks/useMapAgentCompatibilities'
import {usePipelineRunJobAgentCompatibilityStatus} from '../../../../PipelineRunPage/PipelineRunPage.hooks'
import {getRunsOn} from '../../../EditPipelinePage.selectors'
import {isSelfHostedRunsOn} from '../../../EditPipelinePage.utils'

export const useJobAgentCompatibility = (job?: Build | null) => {
  const pipelineId = usePipelineId()
  const pipelineSettingJobId = useMemo(
    () =>
      job?.attributes?.entry?.find(entry => entry?.name === 'teamcity.pipeline.job.id')?.value ??
      '',
    [job],
  )
  const jobAgent = useAppSelector(getRunsOn(pipelineSettingJobId, pipelineId))

  const {isCurrentJobIncompatibilityAgent, compatibilityAgentQueuedJob} =
    usePipelineRunJobAgentCompatibilityStatus(job)
  const {cloudImageAgentCompatibilities, isCurrentAgentIncompatible} =
    useMapAgentCompatibilities(pipelineSettingJobId)

  const isShowNoCompatibleAgent = useMemo(() => {
    const isJobQueued = job?.state === BuildStatusType.QUEUED
    return isJobQueued && (isCurrentJobIncompatibilityAgent || isCurrentAgentIncompatible)
  }, [isCurrentAgentIncompatible, isCurrentJobIncompatibilityAgent, job?.state])

  const incompatibilityAgents = useMemo(() => {
    const isSelfHosted = isSelfHostedRunsOn(jobAgent)
    return isSelfHosted ? compatibilityAgentQueuedJob : cloudImageAgentCompatibilities
  }, [cloudImageAgentCompatibilities, compatibilityAgentQueuedJob, jobAgent])

  return {
    pipelineSettingJobId,
    isShowNoCompatibleAgent,
    incompatibilityAgents,
  }
}
