import {useLocation} from 'react-router'

import ToggleSakuraUI from './ToggleSakuraUI'
import {getClassicUIHref} from './ToggleSakuraUI.utils'

import {useAppSelector} from 'src/hooks/react-redux'

export default function OpenInClassicUI() {
  const location = useLocation()
  const href = useAppSelector(state => getClassicUIHref(state, location))

  return <ToggleSakuraUI href={href} turnOn={false} />
}
