import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog, {type DialogAttrs} from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Header, Content} from '@jetbrains/ring-ui-built/components/island/island'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import type {ReactNode} from 'react'
import {Fragment, memo} from 'react'

import {getAgentsHref} from '../../../../../../../../../routes'
import type {AgentCompatibility} from '../../../../../../services/pipelinesApi.types'

import CompatibleAgentList from './List/CompatibleAgentList'

import styles from './SelfHostedCompatibleAgentDialog.module.css'

interface Props extends DialogAttrs {
  agents?: Array<AgentCompatibility>
  isCloudHosted?: boolean
  subtitleText?: ReactNode
}

function SelfHostedCompatibleAgentDialog(props: Props) {
  const {agents = [], isCloudHosted, subtitleText, onCloseAttempt} = props
  const subTitleText = isCloudHosted ? 'JetBrains-hosted' : 'List of self-hosted'
  const linkOnManageAgets = getAgentsHref()

  return (
    <Dialog trapFocus showCloseButton closeButtonInside contentClassName={styles.dialog} {...props}>
      <Header>{'Agent compatibility'}</Header>
      <Content className={styles.content} scrollableWrapperClassName={styles.scrollableContent}>
        <div className={styles.info}>
          {subtitleText ? (
            subtitleText
          ) : (
            <Fragment>
              <Text>{`${subTitleText} agents based on the compatibility. `}</Text>
              <IconButton
                icon={'new-window'}
                title={'Manage agents'}
                aria-label={'Manage agents'}
                className={styles.textButton}
                iconClassName={styles.icon}
                inline
                href={linkOnManageAgets}
                target="_blank"
                rel="noreferrer"
                childrenLeft
              >
                {'Manage agents'}
              </IconButton>
            </Fragment>
          )}
        </div>
        <CompatibleAgentList agents={agents} />
        <Button className={styles.button} primary onClick={onCloseAttempt}>
          {'Got it'}
        </Button>
      </Content>
    </Dialog>
  )
}

export default memo(SelfHostedCompatibleAgentDialog)
