import {useCallback} from 'react'

import {useSetQueryParam} from '../../../../hooks/routes'

import BuildLogPopup from './BuildLogPopup'
import {setShowLog} from './BuildLogPopup.actions'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

export default function BuildLogPopupContainer() {
  const buildId = useAppSelector(state => state.buildLog.fullLogStates.popup.buildId)

  const setLogView = useSetQueryParam('logView')
  const setLogFilter = useSetQueryParam('logFilter')

  const dispatch = useAppDispatch()
  const onCloseAttempt = useCallback(() => {
    setLogView(null, true)
    setLogFilter(null, true)
    dispatch(setShowLog(null))
  }, [dispatch, setLogFilter, setLogView])

  if (buildId == null) {
    return null
  }

  return <BuildLogPopup onCloseAttempt={onCloseAttempt} />
}
