import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import * as React from 'react'
import {memo} from 'react'

import {useAppSelector} from '../../../../hooks/react-redux'
import Loader from '../../../common/Loader/Loader'
import {FullLogTarget} from '../BuildLog.types'

import styles from './BuildLogPopup.module.css'

const FullBuildLog = React.lazy(
  () =>
    import(
      /* webpackChunkName: "FullBuildLog" */
      '../FullBuildLog/FullBuildLog.container'
    ),
)
const BuildLogPopupHeader = React.lazy(
  () =>
    import(
      /* webpackChunkName: "BuildLogPopupHeader" */
      './BuildLogPopupHeader/BuildLogPopupHeader.container'
    ),
)
type Props = {
  onCloseAttempt: () => unknown
}

function BuildLogPopup({onCloseAttempt}: Props) {
  const marginBottom = useAppSelector(state => state.toolPanelFooter.height)

  return (
    <Dialog
      label="Build Log"
      className={styles.overlay}
      contentClassName={styles.dialog}
      onEscPress={onCloseAttempt}
      onCloseClick={onCloseAttempt}
      style={{marginBottom}}
      autoFocusFirst={false}
      showCloseButton
      closeButtonInside
      trapFocus
      show
    >
      <div className={styles.content}>
        <React.Suspense fallback={<Loader data-suspense-fallback />}>
          <BuildLogPopupHeader />
          <FullBuildLog target={FullLogTarget.POPUP} className={styles.log} />
        </React.Suspense>
      </div>
    </Dialog>
  )
}

export default memo(BuildLogPopup)
