import {useAppDispatch, useAppSelector} from '../../../../hooks/react-redux'
import DebugPanel from '../../../pages/PipelinesPages/EditPipelinePage/EditPipelineChart/DebugPanel/DebugPanel'
import {debug} from '../../../pages/PipelinesPages/EditPipelinePage/slices/EditPipelinePage.slices'
import {useToolPanel} from '../ToolPanelFooter.hooks'
import ToolPanelFooterContent from '../ToolPanelFooterContent/ToolPanelFooterContent'

import {usePipelineId} from 'src/components/pages/PipelinesPages/hooks/pipeline'

function PipelinesToolPanel() {
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()

  const isExpandedPanel = useAppSelector(
    state => state.pipelines.debug[pipelineId]?.isPanelExpanded,
  )
  const onExpand = (expanded: boolean) => {
    dispatch(debug.actions.expandPanel({pipelineId, expanded}))
  }
  const {onExpandToggle, ...props} = useToolPanel(isExpandedPanel, onExpand)

  return (
    <ToolPanelFooterContent {...props}>
      <DebugPanel onExpandToggle={onExpandToggle} />
    </ToolPanelFooterContent>
  )
}

export default PipelinesToolPanel
