import {useCallback, useEffect, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../hooks/react-redux'
import {useQueryParams} from '../../../hooks/routes'
import {isPipelinesEditScreen} from '../../../routes'
import {usePipelineId} from '../../pages/PipelinesPages/hooks/pipeline'

import {
  toolPanelFooterClose,
  toolPanelFooterOpen,
  toolPanelFooterResize,
} from './ToolPanelFooter.actions'
import {COLLAPSED_PANEL_HEIGHT, MIN_PANEL_HEIGHT} from './ToolPanelFooter.consts'
import {getDefaultPanelHeightByWindowHeight, getMaxPanelHeight} from './ToolPanelFooter.utils'

export function useToolPanel(initialExpanded = true, onExpand?: (expanded: boolean) => void) {
  const dispatch = useAppDispatch()
  const [resizeDelta, setResizeDelta] = useState(0)
  const [minPanelHeight, setMinPanelHeight] = useState(
    initialExpanded ? MIN_PANEL_HEIGHT : COLLAPSED_PANEL_HEIGHT,
  )
  const [maxPanelHeight, setMaxPanelHeight] = useState(getMaxPanelHeight())
  const [panelResizingHeight, setPanelResizingHeight] = useState<number | null>(null)
  const [panelHeight, setPanelHeight] = useState(
    getDefaultPanelHeightByWindowHeight() + resizeDelta,
  )
  const [expanded, setExpanded] = useState(initialExpanded)

  const getCalculatedPanelHeight = useCallback((): number => {
    if (!expanded) {
      return COLLAPSED_PANEL_HEIGHT
    }
    if (panelHeight > maxPanelHeight) {
      return maxPanelHeight
    }

    if (panelHeight < MIN_PANEL_HEIGHT) {
      return MIN_PANEL_HEIGHT
    }

    return Math.round(panelHeight)
  }, [expanded, maxPanelHeight, panelHeight])

  useEffect(() => {
    const onWindowResize: () => void = () => {
      setPanelHeight(getDefaultPanelHeightByWindowHeight() + resizeDelta)
      setMaxPanelHeight(getMaxPanelHeight())
    }
    window.addEventListener('resize', onWindowResize)
    return () => window.removeEventListener('resize', onWindowResize)
  }, [resizeDelta])

  const onResize: (
    event: unknown,
    direction: unknown,
    refToElement: unknown,
    delta: {
      height: number
      width: number
    },
  ) => void = (event, direction, refToElement, delta) => {
    setPanelResizingHeight(getCalculatedPanelHeight() + delta.height)
  }

  const onResizeStop = (
    event: unknown,
    direction: unknown,
    refToElement: unknown,
    delta: {
      height: number
      width: number
    },
  ) => {
    if (!expanded) {
      onExpand?.(true)
      setExpanded(true)
    }

    setPanelResizingHeight(null)
    if (delta.height !== 0) {
      let newPanelHeight = getCalculatedPanelHeight() + delta.height

      if (newPanelHeight >= MIN_PANEL_HEIGHT) {
        if (newPanelHeight > maxPanelHeight) {
          newPanelHeight = maxPanelHeight
        }

        setResizeDelta(newPanelHeight - getDefaultPanelHeightByWindowHeight())
        setPanelHeight(newPanelHeight)
        return
      }
      setPanelResizingHeight(null)
    }
  }

  const calculatedPanelHeight = expanded ? getCalculatedPanelHeight() : COLLAPSED_PANEL_HEIGHT
  const height = panelResizingHeight ?? calculatedPanelHeight ?? 0

  const onExpandToggle = (isExpanded: boolean) => {
    setExpanded(isExpanded)
    setMinPanelHeight(isExpanded ? MIN_PANEL_HEIGHT : COLLAPSED_PANEL_HEIGHT)
    dispatch(toolPanelFooterResize(height))
  }

  useEffect(() => {
    dispatch(toolPanelFooterResize(height))
  }, [dispatch, height])

  useEffect(() => {
    dispatch(toolPanelFooterOpen(height))
    return () => {
      dispatch(toolPanelFooterClose())
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return {
    calculatedPanelHeight,
    minPanelHeight,
    maxPanelHeight,
    onResize,
    onResizeStop,
    onExpandToggle,
  }
}

export function useIsDebugPanelOpen() {
  const pipelineId = usePipelineId()
  const queryParams = useQueryParams()
  const isDebugPanelOpen = useAppSelector(state => state.pipelines.debug[pipelineId]?.isPanelOpen)

  return isPipelinesEditScreen(queryParams) && queryParams.yaml !== 'true' && isDebugPanelOpen
}
