import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import {memo, useCallback, useMemo, useState} from 'react'

import {getAgentHref, getAgentTypeHref} from '../../../../../../../../../../routes'
import Grid from '../../../../../../../../../common/Grid/Grid'
import RowGroup from '../../../../../../../../../common/Grid/RowGroup'
import Icon from '../../../../../../../../../common/Icon/Icon'
import ListItem from '../../../../../../../../../common/ListItem/ListItem'
import ChipStatus from '../../../../../../../components/ChipStatus/ChipStatus'
import type {AgentCompatibility} from '../../../../../../../services/pipelinesApi.types'

import CompatibleAgenReasonsColumn from './CompatibleAgenReasonsColumn'

import styles from './CompatibleAgentList.module.css'

const osIconMap: KeyValue<string, string> = {
  windows: 'os-windows',
  macos: 'os-mac',
  mac: 'os-mac',
  linux: 'os-linux',
  solaris: 'os-solaris',
  freebsd: 'os-bsd',
  unix: 'os-unix',
}

enum OrderDirection {
  ASC = 'asc',
  DESC = 'desc',
}

enum OrderByField {
  NAME = 'name',
  STATUS = 'status',
  REQUIREMENTS = 'requirements',
}

interface Props {
  agents: Array<AgentCompatibility>
}

function CompatibleAgentList(props: Props) {
  const {agents} = props
  const [orderBy, setOrderBy] = useState(OrderByField.NAME)
  const [order, setOrder] = useState(OrderDirection.ASC)

  const sortedAgents = useMemo(
    () =>
      [...agents].sort((a, b) => {
        let comparison = 0

        switch (orderBy) {
          case OrderByField.NAME:
            comparison = a.agent.name.localeCompare(b.agent.name)
            break
          case OrderByField.STATUS:
            comparison = a.compatible === b.compatible ? 0 : a.compatible ? -1 : 1
            break
          default:
            break
        }

        return order === OrderDirection.ASC ? comparison : -comparison
      }),
    [agents, orderBy, order],
  )

  const onChangeSorting = useCallback(
    (newOrderBy: OrderByField, priorityOrder: OrderDirection = OrderDirection.ASC) => {
      let newOrder = priorityOrder

      if (newOrderBy === orderBy) {
        newOrder = order === OrderDirection.ASC ? OrderDirection.DESC : OrderDirection.ASC
      }

      setOrderBy(newOrderBy)
      setOrder(newOrder)
    },
    [orderBy, order],
  )

  const renderColumnHeader = (
    type: OrderByField,
    name: string,
    withSorting: boolean,
    priorityOrder?: OrderDirection,
  ) => {
    const icon = order === OrderDirection.ASC ? 'chevron-up' : 'chevron-down'

    return (
      <div
        className={classNames(styles.headerColumn, {
          [styles.nameColumn]: type === OrderByField.NAME,
          [styles.requirementsColumn]: type === OrderByField.REQUIREMENTS,
          [styles.statusColumn]: type === OrderByField.STATUS,
        })}
      >
        {withSorting ? (
          <button
            type="button"
            className={styles.columnTitle}
            onClick={() => onChangeSorting(type, priorityOrder)}
          >
            {name}
            <Icon className={styles.sortIcon} name={orderBy === type ? icon : 'sorting'} />
          </button>
        ) : (
          <span>{name}</span>
        )}
      </div>
    )
  }

  const renderItem = (compatibility: AgentCompatibility) => {
    const compatibilityAgentId = compatibility.agent.id
    const isCompatible = compatibility.compatible
    const linkOnAgent =
      compatibility.agent.type === 'CLOUD_IMAGE'
        ? getAgentTypeHref(compatibilityAgentId)
        : getAgentHref(compatibilityAgentId)

    const osType = compatibility.agent.osType
    const osIcon = osType != null ? (osIconMap[osType.toLowerCase()] ?? 'unknown-os') : 'unknown-os'
    const iconTitle = osType ?? 'Unknown OS'

    return (
      <RowGroup span={2} key={compatibilityAgentId}>
        <ListItem className={styles.item} rowClassName={styles.itemRow} highlightHover hideBorders>
          <div className={styles.itemContent}>
            <div className={styles.nameColumn}>
              <SvgIcon className={styles.osIcon} icon={osIcon} title={iconTitle} />
              <Link target="_blank" rel="noreferrer" href={linkOnAgent}>
                {compatibility.agent.name}
              </Link>
            </div>
            <div className={styles.statusColumn}>
              <ChipStatus status={isCompatible ? 'standard' : 'warning'}>
                {isCompatible ? 'Compatible' : 'Incompatible'}
              </ChipStatus>
            </div>
            <div className={styles.requirementsColumn}>
              <CompatibleAgenReasonsColumn
                compatible={compatibility.compatible}
                unmetReqirements={compatibility.unmetReqirements}
                unresolvedParameters={compatibility.unresolvedParameters}
                invalidRunnerParameters={compatibility.invalidRunnerParameters}
              />
            </div>
          </div>
        </ListItem>
      </RowGroup>
    )
  }

  return (
    <Grid className={styles.grid}>
      <RowGroup>
        <div className={styles.tableHeader}>
          {renderColumnHeader(OrderByField.NAME, 'Agent / Image', true)}
          {renderColumnHeader(OrderByField.STATUS, 'Status', true, OrderDirection.DESC)}
          {renderColumnHeader(OrderByField.REQUIREMENTS, 'Requirements / Errors', false)}
        </div>
      </RowGroup>
      {sortedAgents.map(renderItem)}
    </Grid>
  )
}

export default memo(CompatibleAgentList)
