import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Header} from '@jetbrains/ring-ui-built/components/island/island'
import type {ReactNode} from 'react'
import {memo} from 'react'

import {useBooleanQueryParamState} from '../../../../../../../hooks/routes'
import DebugJobTabs from '../DebugJobTabs/DebugJobTabs'
import commonStyles from '../DebugPanel.module.css'

import styles from './DebugPopup.module.css'

type Props = {
  jobs: number[]
  selectedJobId?: string | null
  onJobSelect: (key: string) => void
  content: ReactNode
  onClose: () => void
}
function DebugPopup({jobs, selectedJobId, onJobSelect, content, onClose}: Props) {
  const [isJobDetailsFullscreen] = useBooleanQueryParamState('jobDetailsFullscreen', false)

  if (!isJobDetailsFullscreen) {
    return null
  }

  return (
    <Dialog
      showCloseButton
      closeButtonInside
      className={styles.overlay}
      contentClassName={styles.dialog}
      show
      label="Debug"
      onCloseClick={onClose}
    >
      <Header className={styles.header}>{'Debug'}</Header>
      <div className={commonStyles.header}>
        <DebugJobTabs jobs={jobs} selectedJobId={selectedJobId} onJobSelect={onJobSelect} />
      </div>
      {content}
    </Dialog>
  )
}

export default memo(DebugPopup)
