import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'

import PluginWrapper from '../../common/Plugin/PluginWrapper/PluginWrapper'

import PipelinesToolPanel from './PipelinesToolPanel/PipelinesToolPanel'
import TerminalToolPanel from './TerminalToolPanel/TerminalToolPanel'
import {useIsDebugPanelOpen} from './ToolPanelFooter.hooks'

function ToolPanelFooter() {
  const isDebugging = useIsDebugPanelOpen()

  if (isDebugging) {
    return <PipelinesToolPanel />
  }

  return (
    <PluginWrapper placeId={PlaceId.SAKURA_TOOL_PANEL_FOOTER}>
      <TerminalToolPanel />
    </PluginWrapper>
  )
}

export default ToolPanelFooter
