import {Tab, Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import classNames from 'classnames'
import {memo} from 'react'

import styles from '../DebugPanel.module.css'

import DebugJobTab from './DebugJobTab/DebugJobTab'

type Props = {
  jobs: number[]
  selectedJobId?: string | null
  onJobSelect: (key: string) => void
}

function DebugJobTabs({jobs, selectedJobId, onJobSelect}: Props) {
  if (!selectedJobId) {
    return null
  }
  return (
    <Tabs
      autoCollapse
      selected={selectedJobId}
      onSelect={onJobSelect}
      className={classNames(styles.tabs, styles.topTabs)}
    >
      {jobs.map(id => (
        <Tab key={id} id={String(id)} className={styles.tab} title={<DebugJobTab jobId={id} />} />
      ))}
    </Tabs>
  )
}
export default memo(DebugJobTabs)
