import Button from '@jetbrains/ring-ui-built/components/button/button'

import {getCompareBuildHref} from '../../../../../routes'
import {stringifyId} from '../../../../../types'
import RouterLinkWrapper from '../../../../common/RouterLinkWrapper/RouterLinkWrapper'

import type {ControlProps} from './CompareBuildAlert.types'

import styles from './CompareBuildAlert.module.css'

function CompareBuildAlertButtons({
  addThisBuild,
  sourceBuildId,
  onCloseRequest,
  showChooseBuildDialog,
  pageBuildId,
}: ControlProps) {
  return (
    <>
      {addThisBuild ? (
        <RouterLinkWrapper>
          <Button
            primary
            href={`${getCompareBuildHref(sourceBuildId)}?withBuildId=${stringifyId(pageBuildId)}`}
            onClick={onCloseRequest}
          >
            {'Add and compare'}
          </Button>
        </RouterLinkWrapper>
      ) : (
        <Button primary onClick={showChooseBuildDialog}>
          {'Add second build...'}
        </Button>
      )}
      <Button inline onClick={onCloseRequest} className={styles.cancel}>
        {'Cancel comparison'}
      </Button>
    </>
  )
}

export default CompareBuildAlertButtons
